'use client'
import { useEffect } from 'react'
import { useRouter } from 'next/navigation'

const NOVA_CSS = "@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent;user-select:none}\nhtml,body{height:100%;background:#050709;font-family:'Inter',-apple-system,sans-serif;color:#e2e8f0;overflow:hidden}\n#bg{position:fixed;inset:0;z-index:0;pointer-events:none}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   EXACT LANDING PAGE ORB (CSS only)\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n.nova-orb{\n  border-radius:50%;\n  background:radial-gradient(circle at 33% 33%,#c4b5fd,#7c3aed 40%,#4c1d95 70%,#08001a);\n  animation:orb-breathe 3.5s ease-in-out infinite;\n  position:relative;\n  flex-shrink:0;\n}\n.nova-gloss{\n  position:absolute;top:18%;left:23%;width:52%;height:37%;\n  background:radial-gradient(ellipse at 42% 42%,rgba(255,255,255,0.26),transparent 70%);\n  border-radius:50%;pointer-events:none;\n}\n@keyframes orb-breathe{\n  0%,100%{box-shadow:0 0 55px rgba(124,58,237,0.7),0 0 120px rgba(109,40,217,0.4),0 0 220px rgba(99,102,241,0.18),inset 0 0 45px rgba(196,181,253,0.2);transform:scale(1)}\n  50%{box-shadow:0 0 80px rgba(124,58,237,0.9),0 0 170px rgba(109,40,217,0.55),0 0 300px rgba(99,102,241,0.28),inset 0 0 65px rgba(196,181,253,0.32);transform:scale(1.05)}\n}\n/* Reactive states */\n.nova-orb.thinking{animation:orb-think 0.8s ease-in-out infinite}\n@keyframes orb-think{\n  0%,100%{box-shadow:0 0 80px rgba(124,58,237,1),0 0 180px rgba(109,40,217,0.7),inset 0 0 70px rgba(196,181,253,0.35);transform:scale(1)}\n  50%{box-shadow:0 0 120px rgba(167,139,250,1),0 0 260px rgba(124,58,237,0.85),inset 0 0 100px rgba(196,181,253,0.5);transform:scale(1.1)}\n}\n.nova-orb.generating{animation:orb-gen 0.4s ease-in-out infinite}\n@keyframes orb-gen{\n  0%,100%{box-shadow:0 0 120px rgba(196,181,253,1),0 0 260px rgba(139,92,246,0.9),inset 0 0 100px rgba(255,255,255,0.4);transform:scale(1.04)}\n  50%{box-shadow:0 0 160px rgba(255,255,255,0.85),0 0 340px rgba(167,139,250,1),inset 0 0 130px rgba(255,255,255,0.55);transform:scale(1.12)}\n}\n\n/* Orbital rings */\n.orb-ring{\n  position:absolute;top:50%;left:50%;\n  border-radius:50%;border-style:solid;\n  transform-origin:center;\n  animation:rorbit linear infinite;\n}\n@keyframes rorbit{\n  from{transform:translate(-50%,-50%) rotate(0deg)}\n  to{transform:translate(-50%,-50%) rotate(360deg)}\n}\n.orb-ring::before{\n  content:'';position:absolute;\n  top:0;left:50%;\n  transform:translate(-50%,-50%);\n  border-radius:50%;\n}\n\n/* \u2500\u2500 HEADER ORB: 32px sphere + small rings \u2500\u2500 */\n.orb-header-wrap{\n  position:relative;\n  width:70px;height:70px; /* enough to contain rings */\n  display:flex;align-items:center;justify-content:center;\n  flex-shrink:0;\n}\n.orb-header-wrap .nova-orb{width:32px;height:32px}\n.orb-header-wrap .nova-orb{\n  box-shadow:0 0 8px rgba(124,58,237,0.9),0 0 18px rgba(109,40,217,0.6),inset 0 0 8px rgba(196,181,253,0.3);\n}\n/* override animation for small orb */\n.orb-header-wrap .nova-orb{animation:orb-breathe-sm 3.5s ease-in-out infinite}\n@keyframes orb-breathe-sm{\n  0%,100%{box-shadow:0 0 8px rgba(124,58,237,0.9),0 0 18px rgba(109,40,217,0.6),inset 0 0 8px rgba(196,181,253,0.3);transform:scale(1)}\n  50%{box-shadow:0 0 12px rgba(124,58,237,1),0 0 28px rgba(109,40,217,0.8),inset 0 0 12px rgba(196,181,253,0.45);transform:scale(1.06)}\n}\n.orb-header-wrap .nova-orb.thinking{animation:orb-think-sm 0.8s ease-in-out infinite}\n@keyframes orb-think-sm{\n  0%,100%{box-shadow:0 0 14px rgba(124,58,237,1),0 0 30px rgba(109,40,217,0.8),inset 0 0 10px rgba(196,181,253,0.4);transform:scale(1)}\n  50%{box-shadow:0 0 20px rgba(167,139,250,1),0 0 44px rgba(124,58,237,0.9),inset 0 0 14px rgba(196,181,253,0.6);transform:scale(1.1)}\n}\n.orb-header-wrap .nova-orb.generating{animation:orb-gen-sm 0.4s ease-in-out infinite}\n@keyframes orb-gen-sm{\n  0%,100%{box-shadow:0 0 20px rgba(196,181,253,1),0 0 40px rgba(139,92,246,0.9),inset 0 0 12px rgba(255,255,255,0.4);transform:scale(1.04)}\n  50%{box-shadow:0 0 28px rgba(255,255,255,0.8),0 0 55px rgba(167,139,250,1),inset 0 0 18px rgba(255,255,255,0.55);transform:scale(1.12)}\n}\n/* Small rings for header */\n.orb-header-wrap .r1{width:50px;height:50px;border-width:1px;border-color:rgba(129,140,248,0.3);animation-duration:7s}\n.orb-header-wrap .r1::before{width:5px;height:5px;background:#818cf8;box-shadow:0 0 6px #818cf8}\n.orb-header-wrap .r2{width:66px;height:66px;border-width:1px;border-color:rgba(167,139,250,0.18);animation-duration:11s;animation-direction:reverse}\n.orb-header-wrap .r2::before{width:4px;height:4px;background:#a78bfa;box-shadow:0 0 5px #a78bfa}\n\n/* Status dot */\n.orb-status{\n  position:absolute;bottom:18px;right:18px;\n  width:10px;height:10px;border-radius:50%;\n  background:#10b981;border:2px solid #050709;\n  box-shadow:0 0 8px rgba(16,185,129,0.8);\n  z-index:10;\n}\n.orb-status.thinking{background:#fbbf24;box-shadow:0 0 8px rgba(251,191,36,0.8);animation:blink .5s ease-in-out infinite alternate}\n.orb-status.generating{background:#818cf8;box-shadow:0 0 8px rgba(129,140,248,0.8);animation:blink .3s ease-in-out infinite alternate}\n@keyframes blink{from{opacity:.5}to{opacity:1}}\n\n/* \u2500\u2500 GREETING ORB: 160px sphere + large rings \u2500\u2500 */\n.orb-greeting-wrap{\n  position:relative;\n  width:100%;\n  height:340px; /* large enough for the 290px ring + some room */\n  display:flex;align-items:center;justify-content:center;\n  margin-bottom:16px;\n}\n.orb-greeting-wrap .nova-orb{width:160px;height:160px;z-index:2}\n.orb-greeting-wrap .r1{width:210px;height:210px;border-width:1px;border-color:rgba(129,140,248,0.22);animation-duration:9s;z-index:1}\n.orb-greeting-wrap .r1::before{width:8px;height:8px;background:#818cf8;box-shadow:0 0 12px #818cf8,0 0 24px rgba(129,140,248,0.5)}\n.orb-greeting-wrap .r2{width:270px;height:270px;border-width:1px;border-color:rgba(167,139,250,0.14);animation-duration:14s;animation-direction:reverse;z-index:1}\n.orb-greeting-wrap .r2::before{width:6px;height:6px;background:#a78bfa;box-shadow:0 0 10px #a78bfa}\n.orb-greeting-wrap .r2::after{content:'';position:absolute;bottom:0;left:50%;transform:translate(-50%,50%);width:4px;height:4px;border-radius:50%;background:#6366f1;box-shadow:0 0 8px #6366f1}\n.orb-greeting-wrap .r3{width:320px;height:320px;border-width:1px;border-color:rgba(99,102,241,0.08);animation-duration:21s;z-index:1}\n.orb-greeting-wrap .r3::before{width:5px;height:5px;background:#c4b5fd;box-shadow:0 0 8px #c4b5fd}\n\n/* \u2500\u2500 MESSAGE AVATAR: tiny orb, no rings \u2500\u2500 */\n.orb-msg{width:24px;height:24px;flex-shrink:0;margin-top:2px}\n.orb-msg.nova-orb{\n  box-shadow:0 0 5px rgba(124,58,237,0.8),0 0 10px rgba(109,40,217,0.5),inset 0 0 4px rgba(196,181,253,0.25);\n  animation:orb-breathe-sm 3.5s ease-in-out infinite;\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 LAYOUT \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n.app{position:fixed;inset:0;z-index:1;display:flex}\n\n/* DESKTOP SIDEBAR */\n.sidebar{width:260px;flex-shrink:0;background:rgba(5,7,9,0.85);backdrop-filter:blur(24px);border-right:1px solid rgba(255,255,255,0.07);display:none;flex-direction:column;padding:28px 0 0}\n.sb-logo{display:flex;align-items:center;gap:10px;padding:0 20px 24px;border-bottom:1px solid rgba(255,255,255,0.06)}\n.sb-logo-ring{position:relative;width:32px;height:32px}\n.sb-logo-spin{position:absolute;inset:-2px;border-radius:9px;background:conic-gradient(#3b82f6,#8b5cf6,#a78bfa,#3b82f6);animation:spin 3s linear infinite}\n.sb-logo-inner{position:absolute;inset:2px;border-radius:6px;background:#080b12;display:flex;align-items:center;justify-content:center}\n.sb-word{font-size:17px;font-weight:800;color:#e2e8f0;letter-spacing:-.02em}\n@keyframes spin{100%{transform:rotate(360deg)}}\n.sb-nav{flex:1;padding:16px 12px;display:flex;flex-direction:column;gap:4px}\n.sb-item{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:12px;cursor:pointer;transition:all .18s;color:rgba(255,255,255,0.45);font-size:14px;font-weight:600}\n.sb-item:hover{background:rgba(255,255,255,0.06);color:rgba(255,255,255,0.8)}\n.sb-item.active{background:rgba(16,185,129,0.1);border:1px solid rgba(16,185,129,0.18);color:#34d399}\n.sb-item svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}\n.sb-section{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:rgba(255,255,255,0.2);padding:12px 12px 6px;margin-top:8px}\n.sb-bottom{padding:16px 12px;border-top:1px solid rgba(255,255,255,0.06)}\n.sb-user{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;cursor:pointer}\n.sb-av{width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,#4f46e5,#7c3aed);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;color:#fff;flex-shrink:0}\n.sb-name{font-size:13px;font-weight:700;color:#e2e8f0}\n.sb-plan{font-size:11px;color:rgba(255,255,255,0.3)}\n\n/* PHONE */\n.phone{flex:1;display:flex;flex-direction:column;min-width:0;max-width:680px;margin:0 auto}\n\n/* TOPBAR */\n.topbar{flex-shrink:0;padding:52px 18px 14px;background:rgba(5,7,9,0.72);backdrop-filter:blur(24px);border-bottom:1px solid rgba(255,255,255,0.07);display:flex;align-items:center;gap:10px}\n.back-btn{width:34px;height:34px;border-radius:50%;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.1);display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0}\n.back-btn svg{width:14px;height:14px;fill:none;stroke:rgba(255,255,255,0.6);stroke-width:2;stroke-linecap:round}\n.nova-info{flex:1;min-width:0}\n.nova-name{font-size:16px;font-weight:800;color:#e2e8f0;letter-spacing:-.02em}\n.nova-state{font-size:11px;color:#10b981;font-weight:500;transition:color .3s}\n.nova-state.thinking{color:#fbbf24}\n.nova-state.generating{color:#818cf8}\n.topbar-btns{display:flex;gap:8px;margin-left:auto;flex-shrink:0}\n.tb-btn{width:34px;height:34px;border-radius:50%;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.09);display:flex;align-items:center;justify-content:center;cursor:pointer;transition:all .15s}\n.tb-btn:active{background:rgba(255,255,255,0.14)}\n.tb-btn svg{width:14px;height:14px;fill:none;stroke:rgba(255,255,255,0.5);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}\n\n/* CONTEXT RIBBON */\n.context-ribbon{flex-shrink:0;padding:8px 16px;background:rgba(5,7,9,0.55);backdrop-filter:blur(12px);border-bottom:1px solid rgba(255,255,255,0.05);display:flex;align-items:center;gap:8px;cursor:pointer}\n.cr-dot{width:6px;height:6px;border-radius:50%;background:#818cf8;flex-shrink:0;animation:cr-pulse 2s ease-in-out infinite}\n@keyframes cr-pulse{0%,100%{opacity:.5}50%{opacity:1}}\n.cr-text{font-size:11px;color:rgba(255,255,255,0.4);flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.cr-text strong{color:rgba(255,255,255,0.7);font-weight:600}\n.cr-due{color:#f87171;font-weight:600}\n.cr-edit{font-size:10px;color:rgba(129,140,248,0.7);font-weight:700;flex-shrink:0;padding:3px 9px;border-radius:100px;background:rgba(129,140,248,0.08);border:1px solid rgba(129,140,248,0.18)}\n\n/* MESSAGES */\n.msgs{flex:1;overflow-y:auto;overflow-x:hidden;padding:14px 14px 6px;display:flex;flex-direction:column;gap:12px;scroll-behavior:smooth}\n.msgs::-webkit-scrollbar{width:3px}\n.msgs::-webkit-scrollbar-thumb{background:rgba(255,255,255,0.08);border-radius:2px}\n\n.msg-nova{display:flex;gap:9px;align-items:flex-start;animation:msg-in .35s cubic-bezier(.23,1,.32,1) both}\n.msg-user{display:flex;flex-direction:row-reverse;gap:9px;align-items:flex-start;animation:msg-in .28s cubic-bezier(.23,1,.32,1) both}\n@keyframes msg-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\n\n.msg-av-user{width:24px;height:24px;border-radius:50%;flex-shrink:0;margin-top:2px;background:linear-gradient(135deg,#4f46e5,#7c3aed);display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:800;color:#fff}\n\n.bubble{border-radius:18px;font-size:13.5px;line-height:1.62;font-weight:450;position:relative}\n.bubble.nova{max-width:86%;padding:11px 14px;background:rgba(8,12,22,0.92);border:1px solid rgba(255,255,255,0.09);color:rgba(255,255,255,0.85);border-bottom-left-radius:5px;backdrop-filter:blur(12px)}\n.bubble.user{max-width:82%;padding:11px 14px;background:linear-gradient(135deg,rgba(79,70,229,0.28),rgba(109,40,217,0.22));border:1px solid rgba(99,102,241,0.3);color:rgba(255,255,255,0.92);border-bottom-right-radius:5px;backdrop-filter:blur(12px)}\n\n/* Rich formatting */\n.hl{background:rgba(129,140,248,0.16);border-radius:4px;padding:1px 5px;color:#a5b4fc;font-weight:600}\n.hl.g{background:rgba(52,211,153,0.12);color:#6ee7b7}\n.hl.a{background:rgba(251,191,36,0.12);color:#fcd34d}\n.hl.r{background:rgba(248,113,113,0.12);color:#fca5a5}\n.steps{display:flex;flex-direction:column;gap:6px;margin-top:8px}\n.step{display:flex;gap:8px;align-items:flex-start}\n.step-n{width:20px;height:20px;border-radius:50%;background:linear-gradient(135deg,#4f46e5,#7c3aed);display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:800;color:#fff;flex-shrink:0;margin-top:1px}\n.step-n.r{background:linear-gradient(135deg,#dc2626,#b91c1c)}\n.step-n.a{background:linear-gradient(135deg,#d97706,#b45309)}\n.step-t{font-size:13px;color:rgba(255,255,255,0.72);line-height:1.5}\n.bfooter{font-size:10px;color:rgba(255,255,255,0.22);margin-top:6px;display:flex;align-items:center;gap:4px}\n.bfooter svg{width:10px;height:10px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round}\n\n/* INLINE CARDS */\n.inline-cards{margin-top:10px;margin-left:-14px;margin-right:-14px}\n.ic-header{display:flex;align-items:center;justify-content:space-between;padding:10px 14px;background:rgba(99,102,241,0.1);border-top:1px solid rgba(99,102,241,0.22);border-left:1px solid rgba(99,102,241,0.22);border-right:1px solid rgba(99,102,241,0.22);border-radius:10px 10px 0 0}\n.ic-title{font-size:12px;font-weight:700;color:#a5b4fc}\n.ic-badge{font-size:10px;font-weight:700;background:rgba(129,140,248,0.15);color:#818cf8;padding:2px 8px;border-radius:100px;border:1px solid rgba(129,140,248,0.2)}\n.ic-card{display:flex;align-items:center;gap:10px;padding:10px 14px;background:rgba(8,12,22,0.88);border-left:1px solid rgba(99,102,241,0.2);border-right:1px solid rgba(99,102,241,0.2);border-bottom:1px solid rgba(255,255,255,0.04);opacity:0;transform:translateY(10px) scale(.97);transition:opacity .35s cubic-bezier(.23,1,.32,1),transform .35s cubic-bezier(.23,1,.32,1)}\n.ic-card.dealt{opacity:1;transform:none}\n.ic-card-dot{width:5px;height:5px;border-radius:50%;background:rgba(129,140,248,0.4);flex-shrink:0}\n.ic-card-q{font-size:12px;font-weight:600;color:#e2e8f0;flex:1;line-height:1.4}\n.ic-study{display:flex;align-items:center;justify-content:center;gap:7px;padding:11px;background:linear-gradient(135deg,rgba(79,70,229,0.18),rgba(109,40,217,0.14));border:1px solid rgba(99,102,241,0.28);border-radius:0 0 10px 10px;cursor:pointer;font-size:12px;font-weight:700;color:#a5b4fc}\n.ic-study svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round}\n\n/* TYPING */\n.typing-wrap{display:flex;gap:9px;align-items:flex-start}\n.typing-bub{padding:12px 16px;background:rgba(8,12,22,0.92);border:1px solid rgba(255,255,255,0.09);border-radius:18px 18px 18px 5px;display:flex;gap:5px;align-items:center;backdrop-filter:blur(12px)}\n.td{width:7px;height:7px;border-radius:50%;background:rgba(129,140,248,0.7);animation:bounce .9s ease-in-out infinite}\n.td:nth-child(2){animation-delay:.15s}.td:nth-child(3){animation-delay:.3s}\n@keyframes bounce{0%,60%,100%{transform:translateY(0);opacity:.5}30%{transform:translateY(-5px);opacity:1}}\n\n/* LONG PRESS ACTIONS */\n.msg-actions{position:absolute;bottom:calc(100%+6px);left:0;background:rgba(8,12,22,0.97);border:1px solid rgba(255,255,255,0.12);border-radius:14px;padding:4px;z-index:50;min-width:196px;backdrop-filter:blur(20px);animation:act-in .2s cubic-bezier(.23,1,.32,1);box-shadow:0 8px 32px rgba(0,0,0,.6)}\n.msg-actions.right{left:auto;right:0}\n@keyframes act-in{from{opacity:0;transform:scale(.92) translateY(6px)}to{opacity:1;transform:none}}\n.action-item{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:10px;cursor:pointer;font-size:13px;font-weight:600;color:rgba(255,255,255,0.8);white-space:nowrap}\n.action-item:active{background:rgba(255,255,255,0.08)}\n.action-item svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;opacity:.6;flex-shrink:0}\n.action-sep{height:1px;background:rgba(255,255,255,0.06);margin:2px 0}\n\n/* NOVA GREETING */\n.nova-greeting{display:flex;flex-direction:column;align-items:center;padding:20px 20px 8px;text-align:center}\n.greeting-h{font-size:20px;font-weight:900;letter-spacing:-.04em;margin-bottom:6px}\n.greeting-h span{background:linear-gradient(135deg,#fff,#a5b4fc);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}\n.greeting-sub{font-size:13px;color:rgba(255,255,255,0.32);line-height:1.6;max-width:260px}\n\n/* REMINDER MODAL */\n.modal-overlay{position:fixed;inset:0;z-index:200;background:rgba(0,0,0,0.6);backdrop-filter:blur(8px);display:flex;align-items:flex-end;animation:fade-in .2s ease}\n@keyframes fade-in{from{opacity:0}to{opacity:1}}\n.modal{background:rgba(10,14,24,0.98);border:1px solid rgba(255,255,255,0.1);border-radius:24px 24px 0 0;padding:20px;width:100%;max-width:680px;margin:0 auto;animation:sheet-in .32s cubic-bezier(.23,1,.32,1)}\n@keyframes sheet-in{from{transform:translateY(100%)}to{transform:none}}\n.modal-handle{width:36px;height:4px;border-radius:2px;background:rgba(255,255,255,0.15);margin:0 auto 20px}\n.modal-title{font-size:17px;font-weight:800;color:#e2e8f0;margin-bottom:4px}\n.modal-sub{font-size:13px;color:rgba(255,255,255,0.35);margin-bottom:20px}\n.modal-tabs{display:flex;background:rgba(255,255,255,0.05);border-radius:12px;padding:4px;margin-bottom:20px}\n.modal-tab{flex:1;padding:9px;border-radius:9px;font-size:13px;font-weight:700;text-align:center;cursor:pointer;transition:all .2s;color:rgba(255,255,255,0.35)}\n.modal-tab.active{background:rgba(255,255,255,0.1);color:#e2e8f0}\n.form-field{margin-bottom:14px}\n.form-label{font-size:11px;font-weight:700;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px;display:block}\n.form-input{width:100%;padding:12px 14px;border-radius:12px;border:1px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.06);color:#e2e8f0;font-size:14px;font-family:inherit;outline:none;transition:border-color .2s}\n.form-input:focus{border-color:rgba(129,140,248,0.45)}\n.form-input::placeholder{color:rgba(255,255,255,0.2)}\n.form-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.form-type-row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}\n.type-chip{padding:8px 14px;border-radius:100px;border:1px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.05);font-size:12px;font-weight:700;cursor:pointer;color:rgba(255,255,255,0.5)}\n.type-chip.selected{background:rgba(99,102,241,0.15);border-color:rgba(99,102,241,0.4);color:#a5b4fc}\n.form-save-btn{width:100%;padding:14px;border-radius:14px;border:none;background:linear-gradient(135deg,#4f46e5,#7c3aed);color:#fff;font-size:15px;font-weight:700;cursor:pointer;font-family:inherit;box-shadow:0 8px 24px rgba(99,102,241,0.35);margin-top:4px}\n.form-cancel{width:100%;padding:13px;border-radius:14px;border:1px solid rgba(255,255,255,0.1);background:none;color:rgba(255,255,255,0.45);font-size:14px;font-weight:600;cursor:pointer;font-family:inherit;margin-top:8px}\n.reminders-list{display:flex;flex-direction:column;gap:8px;margin-bottom:14px;max-height:220px;overflow-y:auto}\n.reminder-item{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:12px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.07)}\n.ri-color{width:10px;height:10px;border-radius:50%;flex-shrink:0}\n.ri-info{flex:1}\n.ri-name{font-size:13px;font-weight:700;color:#e2e8f0}\n.ri-due{font-size:11px;color:rgba(255,255,255,0.35);margin-top:1px}\n.ri-del{width:26px;height:26px;border-radius:50%;background:rgba(239,68,68,0.1);border:1px solid rgba(239,68,68,0.2);display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0}\n.ri-del svg{width:11px;height:11px;fill:none;stroke:#f87171;stroke-width:2;stroke-linecap:round}\n\n/* + MENU */\n.plus-menu{position:absolute;bottom:calc(100%+10px);left:14px;background:rgba(8,12,22,0.97);border:1px solid rgba(255,255,255,0.12);border-radius:18px;padding:6px;backdrop-filter:blur(24px);box-shadow:0 16px 48px rgba(0,0,0,.6);animation:plus-in .22s cubic-bezier(.23,1,.32,1);z-index:50;min-width:210px}\n@keyframes plus-in{from{opacity:0;transform:scale(.9) translateY(10px)}to{opacity:1;transform:none}}\n.pm-item{display:flex;align-items:center;gap:11px;padding:11px 14px;border-radius:12px;cursor:pointer}\n.pm-item:active{background:rgba(255,255,255,0.08)}\n.pm-ico{width:32px;height:32px;border-radius:9px;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.pm-ico svg{width:14px;height:14px;fill:none;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}\n.pm-label{font-size:13px;font-weight:700;color:rgba(255,255,255,0.8)}\n.pm-desc{font-size:11px;color:rgba(255,255,255,0.3)}\n\n/* INPUT BAR */\n.input-bar{flex-shrink:0;padding:10px 14px 28px;background:rgba(5,7,9,0.85);backdrop-filter:blur(24px);border-top:1px solid rgba(255,255,255,0.07);position:relative}\n.input-row{display:flex;gap:9px;align-items:flex-end}\n.plus-btn{width:42px;height:42px;border-radius:50%;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.1);display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;transition:all .22s;font-size:22px;color:rgba(255,255,255,0.5);font-weight:300;line-height:1}\n.plus-btn.open{transform:rotate(45deg);background:rgba(239,68,68,0.12);border-color:rgba(239,68,68,0.3);color:#f87171}\n.input-field{flex:1;min-height:42px;max-height:110px;border-radius:21px;background:rgba(255,255,255,0.06);border:1.5px solid rgba(255,255,255,0.1);padding:11px 16px;font-size:14px;color:#e2e8f0;font-family:inherit;outline:none;resize:none;line-height:1.4;transition:border-color .2s}\n.input-field:focus{border-color:rgba(129,140,248,0.4)}\n.input-field::placeholder{color:rgba(255,255,255,0.2)}\n.mic-btn{width:42px;height:42px;border-radius:50%;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.1);display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0}\n.mic-btn svg{width:16px;height:16px;fill:none;stroke:rgba(255,255,255,0.5);stroke-width:1.5;stroke-linecap:round}\n.mic-btn.on{background:rgba(239,68,68,0.15);border-color:rgba(239,68,68,0.4);animation:mic-p 1s ease-in-out infinite}\n.mic-btn.on svg{stroke:#f87171}\n@keyframes mic-p{0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,0.4)}50%{box-shadow:0 0 0 8px rgba(239,68,68,0)}}\n.send-btn{width:42px;height:42px;border-radius:50%;background:linear-gradient(135deg,#4f46e5,#7c3aed);display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;box-shadow:0 4px 16px rgba(99,102,241,0.4)}\n.send-btn:active{transform:scale(.9)}\n.send-btn svg{width:16px;height:16px;fill:none;stroke:#fff;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n\n/* BOTTOM NAV \u2014 untouched */\n.bottom-nav{flex-shrink:0;padding:10px 0 28px;background:rgba(5,7,9,0.9);backdrop-filter:blur(20px);border-top:1px solid rgba(255,255,255,0.07);display:flex;justify-content:space-around}\n.nav-item{display:flex;flex-direction:column;align-items:center;gap:3px;padding:6px 18px;cursor:pointer;opacity:.3;transition:opacity .2s}\n.nav-item.active{opacity:1}\n.nav-item svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}\n.nav-item.active svg{stroke:#10b981}\n.nav-item span{font-size:10px;font-weight:600}\n.nav-item.active span{color:#10b981}\n\n/* DESKTOP */\n@media(min-width:768px){\n  .sidebar{display:flex}\n  .topbar{padding:20px 24px 16px}\n  .back-btn{display:none}\n  .bottom-nav{display:none}\n  .phone{border-right:1px solid rgba(255,255,255,0.06)}\n}\n"
const NOVA_JS = "// \u2550\u2550 FLUID BACKGROUND \u2550\u2550\n(function(){\n  var c=document.getElementById('bg');\n  c.style.cssText='position:fixed;inset:0;width:100%;height:100%;z-index:0;pointer-events:none';\n  var gl=c.getContext('webgl');if(!gl)return;\n  function resize(){c.width=innerWidth;c.height=innerHeight;gl.viewport(0,0,c.width,c.height);}\n  resize();window.addEventListener('resize',resize);\n  var VS=`attribute vec2 aP;varying vec2 vU;void main(){vU=aP*.5+.5;gl_Position=vec4(aP,.999,1.);}`;\n  var FS=`precision highp float;uniform float uT;uniform vec2 uR;uniform float uRipple;uniform float uRippleT;varying vec2 vU;\n  vec2 h2(vec2 p){p=vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3)));return -1.+2.*fract(sin(p)*43758.545);}\n  float n(vec2 p){vec2 i=floor(p),f=fract(p),u=f*f*f*(f*(f*6.-15.)+10.);return mix(mix(dot(h2(i),f),dot(h2(i+vec2(1,0)),f-vec2(1,0)),u.x),mix(dot(h2(i+vec2(0,1)),f-vec2(0,1)),dot(h2(i+vec2(1,1)),f-vec2(1,1)),u.x),u.y);}\n  float fbm(vec2 p){float v=0.,a=.5;mat2 r=mat2(.8,-.6,.6,.8);for(int i=0;i<6;i++){v+=a*n(p);p=r*p*2.01;a*=.52;}return v;}\n  void main(){vec2 uv=vU;float ar=uR.x/uR.y;uv.x*=ar;float t=uT*.06;\n  vec2 orbPos=vec2(.5*ar,.1);float dist=length(uv-orbPos);\n  float rw=sin(dist*20.-uRippleT*12.)/(dist*8.+1.)*uRipple*0.035;\n  uv+=normalize(uv-orbPos)*rw;\n  vec2 q=vec2(fbm(uv*1.7+t),fbm(uv*1.7+vec2(5.2,1.3)+t*.8));\n  vec2 r=vec2(fbm(uv*1.7+3.4*q+t*.6),fbm(uv*1.7+3.4*q+vec2(8.3,2.8)+t*.45));\n  float f=fbm(uv*1.7+3.4*r+t*.3);f=clamp(f,0.,1.);\n  vec3 col=mix(vec3(.010,.018,.10),vec3(.12,.022,.28),smoothstep(0.,.47,f));\n  col=mix(col,vec3(.30,.06,.60),smoothstep(.27,.67,f));col=mix(col,vec3(.68,.12,.88),smoothstep(.51,.83,f));\n  vec2 vig=vU-.5;col*=clamp(1.-dot(vig,vig)*1.8,.0,1.);col+=.01;gl_FragColor=vec4(col,1.);}`;\n  function mkS(t,s){var sh=gl.createShader(t);gl.shaderSource(sh,s);gl.compileShader(sh);return sh;}\n  var prog=gl.createProgram();gl.attachShader(prog,mkS(gl.VERTEX_SHADER,VS));gl.attachShader(prog,mkS(gl.FRAGMENT_SHADER,FS));gl.linkProgram(prog);\n  var buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);\n  var uT=gl.getUniformLocation(prog,'uT'),uR=gl.getUniformLocation(prog,'uR'),\n      uRipple=gl.getUniformLocation(prog,'uRipple'),uRippleT=gl.getUniformLocation(prog,'uRippleT'),\n      aP=gl.getAttribLocation(prog,'aP');\n  window._bgRipple=0;var t=0,rT=0;\n  (function draw(){requestAnimationFrame(draw);t+=.009;\n    if(window._bgRipple>0){window._bgRipple=Math.max(0,window._bgRipple-.016);rT+=.1;}\n    gl.clearColor(.02,.03,.06,1);gl.clear(gl.COLOR_BUFFER_BIT);gl.useProgram(prog);\n    gl.uniform1f(uT,t);gl.uniform2f(uR,c.width,c.height);\n    gl.uniform1f(uRipple,window._bgRipple);gl.uniform1f(uRippleT,rT);\n    gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.enableVertexAttribArray(aP);\n    gl.vertexAttribPointer(aP,2,gl.FLOAT,false,0,0);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);\n  })();\n})();\n\n// \u2550\u2550 ORB STATE \u2550\u2550\nfunction setNovaState(s){\n  var stateEl=document.getElementById('nova-state');\n  var dot=document.getElementById('orb-status');\n  var topOrb=document.getElementById('topbar-orb');\n  var gtOrb=document.getElementById('greeting-orb');\n  // Update state text and dot class\n  stateEl.className='nova-state'+(s==='idle'?'':' '+s);\n  dot.className='orb-status'+(s==='idle'?'':' '+s);\n  // Update orb animation \u2014 preserve the base nova-orb class\n  [topOrb,gtOrb].forEach(function(o){if(!o)return;o.className='nova-orb'+(s==='idle'?'':' '+s);});\n  var txt={idle:'Online \u00b7 ready to help',thinking:'Thinking...',generating:'Generating...'};\n  stateEl.textContent=txt[s]||txt.idle;\n  if(s==='generating') window._bgRipple=2.0;\n}\n\n// \u2550\u2550 REMINDERS \u2550\u2550\nvar reminders=[\n  {id:1,type:'assignment',name:'Cell Biology lab report',subject:'Cell Biology',due:'Tomorrow',color:'#f87171'},\n  {id:2,type:'assignment',name:'Chapter 7 worksheet',subject:'Cell Biology',due:'Friday',color:'#fbbf24'},\n  {id:3,type:'test',name:'Biology mid-term',subject:'Cell Biology',due:'Next Monday',color:'#818cf8'},\n];\nvar nextId=4,selectedType='assignment',modalTab='add';\n\nfunction updateRibbon(){\n  var asgn=reminders.filter(function(r){return r.type==='assignment';}).length;\n  var tests=reminders.filter(function(r){return r.type==='test'||r.type==='quiz';}).length;\n  var subj=reminders[0]?reminders[0].subject:'No classes added';\n  var parts=[];\n  if(asgn) parts.push('<span class=\"cr-due\">'+asgn+' assignment'+(asgn>1?'s':'')+' due</span>');\n  if(tests) parts.push('<span style=\"color:#818cf8;font-weight:600\">'+tests+' test'+(tests>1?'s':'')+' coming up</span>');\n  document.getElementById('cr-text').innerHTML='<strong>'+subj+'</strong>'+(parts.length?' \u00b7 '+parts.join(' \u00b7 '):'');\n}\n\nfunction openReminders(){\n  var overlay=document.createElement('div');\n  overlay.className='modal-overlay';overlay.id='modal-overlay';\n  overlay.onclick=function(e){if(e.target===overlay)closeModal();};\n  overlay.innerHTML='<div class=\"modal\"><div class=\"modal-handle\"></div><div class=\"modal-title\">Reminders</div><div class=\"modal-sub\">Auto-sync when your school connects \u00b7 or add manually below</div><div class=\"modal-tabs\"><div class=\"modal-tab '+(modalTab==='view'?'active':'')+'\" onclick=\"switchTab(\\'view\\')\">Current ('+reminders.length+')</div><div class=\"modal-tab '+(modalTab==='add'?'active':'')+'\" onclick=\"switchTab(\\'add\\')\">Add new</div></div><div id=\"modal-body\"></div></div>';\n  document.body.appendChild(overlay);\n  renderModalBody();\n}\nfunction switchTab(tab){\n  modalTab=tab;\n  document.querySelectorAll('.modal-tab').forEach(function(t,i){t.classList.toggle('active',(i===0&&tab==='view')||(i===1&&tab==='add'));});\n  renderModalBody();\n}\nfunction renderModalBody(){\n  var body=document.getElementById('modal-body');if(!body)return;\n  if(modalTab==='view'){\n    var list=reminders.length?reminders.map(function(r){return'<div class=\"reminder-item\"><div class=\"ri-color\" style=\"background:'+r.color+'\"></div><div class=\"ri-info\"><div class=\"ri-name\">'+r.name+'</div><div class=\"ri-due\">'+(r.type==='assignment'?'\ud83d\udccb Assignment':'\ud83d\udcdd '+r.type[0].toUpperCase()+r.type.slice(1))+' \u00b7 Due '+r.due+'</div></div><div class=\"ri-del\" onclick=\"deleteReminder('+r.id+')\"><svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></div></div>';}).join(''):'<div style=\"text-align:center;padding:24px;color:rgba(255,255,255,0.25);font-size:13px\">No reminders yet</div>';\n    body.innerHTML='<div class=\"reminders-list\">'+list+'</div><button class=\"form-save-btn\" style=\"background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.1);box-shadow:none;color:rgba(255,255,255,0.6)\" onclick=\"switchTab(\\'add\\')\">+ Add reminder</button><button class=\"form-cancel\" onclick=\"closeModal()\">Done</button>';\n  } else {\n    var d=new Date();d.setDate(d.getDate()+1);\n    body.innerHTML='<div class=\"form-field\"><label class=\"form-label\">Type</label><div class=\"form-type-row\"><div class=\"type-chip selected\" id=\"tc-assignment\" onclick=\"selectType(\\'assignment\\')\">\ud83d\udccb Assignment</div><div class=\"type-chip\" id=\"tc-test\" onclick=\"selectType(\\'test\\')\">\ud83d\udcdd Test</div><div class=\"type-chip\" id=\"tc-quiz\" onclick=\"selectType(\\'quiz\\')\">\u26a1 Quiz</div></div></div><div class=\"form-field\"><label class=\"form-label\">Title</label><input class=\"form-input\" id=\"r-name\" placeholder=\"e.g. Cell Biology lab report\"></div><div class=\"form-row\"><div class=\"form-field\"><label class=\"form-label\">Subject</label><input class=\"form-input\" id=\"r-subject\" placeholder=\"e.g. Biology\"></div><div class=\"form-field\"><label class=\"form-label\">Due date</label><input class=\"form-input\" id=\"r-due\" type=\"date\" value=\"'+d.toISOString().split('T')[0]+'\"></div></div><button class=\"form-save-btn\" onclick=\"saveReminder()\">Save reminder</button><button class=\"form-cancel\" onclick=\"closeModal()\">Cancel</button>';\n  }\n}\nfunction selectType(t){\n  selectedType=t;\n  ['assignment','test','quiz'].forEach(function(x){var el=document.getElementById('tc-'+x);if(el)el.classList.toggle('selected',x===t);});\n}\nfunction saveReminder(){\n  var name=document.getElementById('r-name')?.value.trim();\n  if(!name){document.getElementById('r-name').focus();return;}\n  var subject=document.getElementById('r-subject')?.value.trim()||'General';\n  var dueRaw=document.getElementById('r-due')?.value;\n  var dueDate=dueRaw?new Date(dueRaw):new Date();\n  var diff=Math.ceil((dueDate-new Date())/(1000*60*60*24));\n  var dueStr=diff<=0?'Today':diff===1?'Tomorrow':diff<=7?dueDate.toLocaleDateString('en',{weekday:'long'}):dueDate.toLocaleDateString('en',{month:'short',day:'numeric'});\n  var colors={assignment:'#f87171',test:'#818cf8',quiz:'#fbbf24'};\n  reminders.push({id:nextId++,type:selectedType,name:name,subject:subject,due:dueStr,color:colors[selectedType]});\n  updateRibbon();closeModal();\n}\nfunction deleteReminder(id){reminders=reminders.filter(function(r){return r.id!==id;});updateRibbon();renderModalBody();}\nfunction closeModal(){var o=document.getElementById('modal-overlay');if(o)o.remove();}\n\n// \u2550\u2550 CHAT \u2550\u2550\nvar msgs=document.getElementById('msgs');\nvar greeting=document.getElementById('greeting');\nvar greetingGone=false,longPressTimer=null,currentActions=null;\n\nfunction hideGreeting(){\n  if(greetingGone)return;greetingGone=true;\n  greeting.style.transition='opacity .3s ease,transform .3s ease';\n  greeting.style.opacity='0';greeting.style.transform='scale(.95)';\n  setTimeout(function(){greeting.remove();},300);\n}\n\nfunction makeNovaAv(){\n  var d=document.createElement('div');\n  d.style.cssText='position:relative;flex-shrink:0;margin-top:2px';\n  var orb=document.createElement('div');\n  orb.className='nova-orb orb-msg';\n  orb.style.cssText='width:24px;height:24px';\n  var gloss=document.createElement('div');gloss.className='nova-gloss';\n  orb.appendChild(gloss);d.appendChild(orb);\n  return d;\n}\nfunction makeUserAv(){\n  var d=document.createElement('div');d.className='msg-av-user';d.textContent='G';return d;\n}\n\nfunction addUser(text){\n  var wrap=document.createElement('div');wrap.className='msg-user';\n  var bub=document.createElement('div');bub.className='bubble user';bub.textContent=text;\n  setupLongPress(bub,true);\n  wrap.appendChild(makeUserAv());wrap.appendChild(bub);\n  msgs.appendChild(wrap);scrollDown();\n}\n\nfunction addTyping(){\n  var wrap=document.createElement('div');wrap.className='typing-wrap';wrap.id='typing';\n  var bub=document.createElement('div');bub.className='typing-bub';\n  bub.innerHTML='<div class=\"td\"></div><div class=\"td\"></div><div class=\"td\"></div>';\n  wrap.appendChild(makeNovaAv());wrap.appendChild(bub);\n  msgs.appendChild(wrap);scrollDown();\n}\nfunction removeTyping(){var t=document.getElementById('typing');if(t)t.remove();}\n\nfunction streamText(el,html){\n  el.innerHTML='';var i=0;\n  function next(){\n    if(i>=html.length){el.innerHTML=html;scrollDown();return;}\n    if(html[i]==='<'){while(i<html.length&&html[i]!=='>'){i++;}i++;}else{i++;}\n    el.innerHTML=html.slice(0,i);scrollDown();\n    setTimeout(next,11);\n  }\n  next();\n}\n\nfunction addNovaBubble(html,type,extra){\n  var wrap=document.createElement('div');wrap.className='msg-nova';\n  var bub=document.createElement('div');bub.className='bubble nova';\n  setupLongPress(bub,false);\n  wrap.appendChild(makeNovaAv());wrap.appendChild(bub);\n  msgs.appendChild(wrap);\n  if(type==='cards'){\n    bub.textContent=extra.intro;\n    setTimeout(function(){dealCards(bub,extra.cards);},500);\n  } else {\n    streamText(bub,html);\n  }\n  scrollDown();\n}\n\nfunction dealCards(bub,cards){\n  setNovaState('generating');window._bgRipple=2.0;\n  var wrap=document.createElement('div');wrap.className='inline-cards';\n  var hdr=document.createElement('div');hdr.className='ic-header';\n  hdr.innerHTML='<div class=\"ic-title\">\u2726 '+cards.length+' flashcards generated</div><div class=\"ic-badge\">Cell Biology</div>';\n  wrap.appendChild(hdr);\n  var cw=document.createElement('div');\n  cards.forEach(function(q){\n    var row=document.createElement('div');row.className='ic-card';\n    row.innerHTML='<div class=\"ic-card-dot\"></div><div class=\"ic-card-q\">'+q+'</div>';\n    cw.appendChild(row);\n  });\n  wrap.appendChild(cw);\n  var study=document.createElement('div');study.className='ic-study';\n  study.innerHTML='<svg viewBox=\"0 0 24 24\"><path d=\"M4 19.5A2.5 2.5 0 016.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 014 19.5v-15A2.5 2.5 0 016.5 2z\"/></svg>Study these now \u2192';\n  wrap.appendChild(study);bub.appendChild(wrap);scrollDown();\n  var rows=cw.querySelectorAll('.ic-card');\n  rows.forEach(function(row,i){\n    setTimeout(function(){row.classList.add('dealt');scrollDown();if(i===rows.length-1)setTimeout(function(){setNovaState('idle');},500);},80+i*110);\n  });\n}\n\nfunction setupLongPress(el,isUser){\n  var fire=function(){if(navigator.vibrate)navigator.vibrate(22);showActions(el,isUser);};\n  el.addEventListener('touchstart',function(){longPressTimer=setTimeout(fire,460);},{passive:true});\n  el.addEventListener('touchend',function(){clearTimeout(longPressTimer);});\n  el.addEventListener('touchmove',function(){clearTimeout(longPressTimer);});\n  el.addEventListener('mousedown',function(){longPressTimer=setTimeout(fire,460);});\n  el.addEventListener('mouseup',function(){clearTimeout(longPressTimer);});\n}\n\nfunction showActions(el,isUser){\n  hideActions();\n  el.style.transform='scale(.97)';setTimeout(function(){el.style.transform='';},180);\n  var acts=isUser?[\n    {ico:'<path d=\"M4 19.5A2.5 2.5 0 016.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 014 19.5v-15A2.5 2.5 0 016.5 2z\"/>',lbl:'Make flashcards from this'},\n    {ico:'<path d=\"M9 11l3 3L22 4\"/>',lbl:'Quiz me on this'},\n    {ico:'<path d=\"M4 12v8a2 2 0 002 2h12a2 2 0 002-2v-8\"/><polyline points=\"16 6 12 2 8 6\"/><line x1=\"12\" y1=\"2\" x2=\"12\" y2=\"15\"/>',lbl:'Copy message'},\n  ]:[\n    {ico:'<path d=\"M4 19.5A2.5 2.5 0 016.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 014 19.5v-15A2.5 2.5 0 016.5 2z\"/>',lbl:'Make flashcards from this'},\n    {ico:'<path d=\"M9 11l3 3L22 4\"/>',lbl:'Quiz me on this'},\n    {ico:'<polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/>',lbl:'Save this explanation'},\n    {ico:'<path d=\"M4 12v8a2 2 0 002 2h12a2 2 0 002-2v-8\"/><polyline points=\"16 6 12 2 8 6\"/><line x1=\"12\" y1=\"2\" x2=\"12\" y2=\"15\"/>',lbl:'Copy message'},\n  ];\n  var menu=document.createElement('div');\n  menu.className='msg-actions'+(isUser?' right':'');menu.id='msg-actions';\n  acts.forEach(function(a,i){\n    var item=document.createElement('div');item.className='action-item';\n    item.innerHTML='<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\">'+a.ico+'</svg>'+a.lbl;\n    item.onclick=hideActions;menu.appendChild(item);\n    if(i<acts.length-1){var sep=document.createElement('div');sep.className='action-sep';menu.appendChild(sep);}\n  });\n  el.style.position='relative';el.appendChild(menu);\n  currentActions={el:el,menu:menu};\n  setTimeout(function(){\n    document.addEventListener('touchstart',hideActionsOut);\n    document.addEventListener('click',hideActionsOut);\n  },10);\n}\nfunction hideActionsOut(e){if(currentActions&&!currentActions.menu.contains(e.target))hideActions();}\nfunction hideActions(){\n  if(currentActions){currentActions.menu.remove();currentActions=null;\n    document.removeEventListener('touchstart',hideActionsOut);document.removeEventListener('click',hideActionsOut);}\n}\n\n// Responses\nvar RESP={\n  cards:{type:'cards',intro:'Done \u2014 6 flashcards on Cell Biology, focused on your weak spots.',cards:['What is the powerhouse of the cell?','What is the function of the cell membrane?','Describe the role of ribosomes.','What is osmosis?','Difference between mitosis and meiosis?','What does the nucleus control?']},\n  explain:{type:'rich',html:'Great question \u2014 they\\'re easy to mix up!<br><br><span class=\"hl\">Diffusion</span> is the broad concept: any molecule moving from high to low concentration.<br><br><span class=\"hl g\">Osmosis</span> is a specific type \u2014 only <strong style=\"color:#a5b4fc\">water</strong> crossing a <span class=\"hl a\">semi-permeable membrane</span>.<br><br><div class=\"steps\"><div class=\"step\"><div class=\"step-n\">1</div><div class=\"step-t\">All osmosis is diffusion</div></div><div class=\"step\"><div class=\"step-n\">2</div><div class=\"step-t\">Not all diffusion is osmosis</div></div><div class=\"step\"><div class=\"step-n\">3</div><div class=\"step-t\">Osmosis = water only, through a membrane</div></div></div><div class=\"bfooter\"><svg viewBox=\"0 0 16 16\"><path d=\"M2 8l4 4 8-8\"/></svg>Want me to build flashcards on this?</div>'},\n  quiz:{type:'rich',html:'Let\\'s go! Answer below and I\\'ll give instant feedback.<br><br><div style=\"background:rgba(99,102,241,0.1);border:1px solid rgba(99,102,241,0.22);border-radius:12px;padding:14px;margin-top:4px\"><div style=\"font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:#818cf8;margin-bottom:8px\">Question 1 of 5</div><div style=\"font-size:14px;font-weight:700;color:#e2e8f0;line-height:1.4\">What process do plants use to convert sunlight into glucose?</div></div>'},\n  assignment:{type:'rich',html:'You have <span class=\"hl r\">2 assignments due</span> and <span class=\"hl\">1 test coming up</span>:<br><br><div class=\"steps\"><div class=\"step\"><div class=\"step-n r\">!</div><div class=\"step-t\"><strong style=\"color:#fca5a5\">Cell Biology lab report</strong> \u2014 due tomorrow</div></div><div class=\"step\"><div class=\"step-n a\">2</div><div class=\"step-t\"><strong style=\"color:#fcd34d\">Chapter 7 worksheet</strong> \u2014 due Friday</div></div><div class=\"step\"><div class=\"step-n\">3</div><div class=\"step-t\"><strong style=\"color:#a5b4fc\">Biology mid-term</strong> \u2014 next Monday</div></div></div><br>Want me to help with any of these now?'}\n};\n\nfunction sendMessage(){\n  var text=document.getElementById('input-field').value.trim();if(!text)return;\n  document.getElementById('input-field').value='';autoResize(document.getElementById('input-field'));\n  hideGreeting();addUser(text);setNovaState('thinking');addTyping();\n  var lc=text.toLowerCase();\n  var resp;\n  if(lc.includes('flashcard')||lc.includes('card')) resp=RESP.cards;\n  else if(lc.includes('osmosis')||lc.includes('explain')||lc.includes('diffusion')) resp=RESP.explain;\n  else if(lc.includes('quiz')||lc.includes('test me')) resp=RESP.quiz;\n  else if(lc.includes('assignment')||lc.includes('due')||lc.includes('homework')) resp=RESP.assignment;\n  else resp={type:'rich',html:'I can help with <span class=\"hl\">'+text.slice(0,40)+(text.length>40?'...':'')+'</span>. Want me to explain it, create flashcards, or quiz you on it?'};\n  setTimeout(function(){\n    removeTyping();\n    if(resp.type==='cards'){setNovaState('generating');addNovaBubble(null,'cards',resp);}\n    else{setNovaState('idle');addNovaBubble(resp.html,'rich',null);}\n  },1100+Math.random()*600);\n}\n\nvar plusOpen=false;\nfunction togglePlus(){\n  plusOpen=!plusOpen;\n  document.getElementById('plus-btn').classList.toggle('open',plusOpen);\n  var wrap=document.getElementById('plus-menu-wrap');\n  if(plusOpen){\n    var menu=document.createElement('div');menu.className='plus-menu';menu.id='plus-menu';\n    menu.innerHTML='<div class=\"pm-item\" onclick=\"sendPrompt(\\'Make me flashcards on Cell Biology\\');togglePlus()\"><div class=\"pm-ico\" style=\"background:rgba(99,102,241,0.14);border:1px solid rgba(99,102,241,0.22)\"><svg viewBox=\"0 0 24 24\" stroke=\"#818cf8\" stroke-width=\"1.5\" stroke-linecap=\"round\"><path d=\"M4 19.5A2.5 2.5 0 016.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 014 19.5v-15A2.5 2.5 0 016.5 2z\"/></svg></div><div><div class=\"pm-label\">Flashcards</div><div class=\"pm-desc\">Generate from any topic</div></div></div><div class=\"pm-item\" onclick=\"sendPrompt(\\'Quiz me on my classes\\');togglePlus()\"><div class=\"pm-ico\" style=\"background:rgba(251,191,36,0.12);border:1px solid rgba(251,191,36,0.22)\"><svg viewBox=\"0 0 24 24\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-linecap=\"round\"><path d=\"M9 11l3 3L22 4\"/></svg></div><div><div class=\"pm-label\">Quick Quiz</div><div class=\"pm-desc\">Test yourself on a topic</div></div></div><div class=\"pm-item\" onclick=\"openReminders();if(plusOpen)togglePlus()\"><div class=\"pm-ico\" style=\"background:rgba(248,113,113,0.1);border:1px solid rgba(248,113,113,0.22)\"><svg viewBox=\"0 0 24 24\" stroke=\"#f87171\" stroke-width=\"1.5\" stroke-linecap=\"round\"><path d=\"M18 8A6 6 0 006 8c0 7-3 9-3 9h18s-3-2-3-9\"/><path d=\"M13.73 21a2 2 0 01-3.46 0\"/></svg></div><div><div class=\"pm-label\">Assignments & Tests</div><div class=\"pm-desc\">Add or view reminders</div></div></div>';\n    wrap.appendChild(menu);\n    setTimeout(function(){document.addEventListener('click',closePlusOut);},10);\n  } else {\n    var m=document.getElementById('plus-menu');if(m)m.remove();\n    document.removeEventListener('click',closePlusOut);\n  }\n}\nfunction closePlusOut(e){\n  var btn=document.getElementById('plus-btn'),menu=document.getElementById('plus-menu');\n  if(plusOpen&&!menu?.contains(e.target)&&e.target!==btn){plusOpen=false;btn.classList.remove('open');if(menu)menu.remove();document.removeEventListener('click',closePlusOut);}\n}\nfunction sendPrompt(text){document.getElementById('input-field').value=text;sendMessage();}\n\nvar micActive=false;\nfunction toggleMic(){\n  micActive=!micActive;\n  var btn=document.getElementById('mic-btn');btn.classList.toggle('on',micActive);\n  if(navigator.vibrate)navigator.vibrate(micActive?[8,30,8]:15);\n  if(micActive){\n    setNovaState('thinking');document.getElementById('nova-state').textContent='\ud83c\udf99 Listening...';\n    setTimeout(function(){micActive=false;btn.classList.remove('on');document.getElementById('input-field').value='Explain osmosis vs diffusion';autoResize(document.getElementById('input-field'));setNovaState('idle');},2000);\n  }\n}\nfunction handleKey(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage();}}\nfunction autoResize(el){el.style.height='auto';el.style.height=Math.min(el.scrollHeight,110)+'px';}\nfunction scrollDown(){setTimeout(function(){msgs.scrollTop=msgs.scrollHeight;},30);}\n\nupdateRibbon();\n"
