export default function NovaPage() {
  const router = useRouter()
  useEffect(() => {
    const style = document.createElement('style')
    style.id = 'nova-css'
    style.textContent = NOVA_CSS
    document.head.appendChild(style)
    const script = document.createElement('script')
    script.id = 'nova-js'
    script.textContent = NOVA_JS
    document.body.appendChild(script)
    return () => {
      document.getElementById('nova-css')?.remove()
      document.getElementById('nova-js')?.remove()
    }
  }, [router])
  return <div suppressHydrationWarning dangerouslySetInnerHTML={{ __html: NOVA_HTML }} />
}
